<?php
declare(strict_types=1);
require dirname(__DIR__) . '/auth_store.php';
header('Content-Type: application/json; charset=UTF-8');
header('Cache-Control: no-store, no-cache, must-revalidate');
const TT_PFO_FILE=TT_DATA_DIR.'/accounts.json';
const TT_PFO_OPS=TT_DATA_DIR.'/operations.json';
function pfo_out(array $d,int $s=200):never{http_response_code($s);echo json_encode($d,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function pfo_can_write(array $u):bool{if(($u['role']??'')==='Super Admin')return true;$p=$u['permissions']['Accounts']??null;if($p==='all')return true;if(!is_array($p))return false;if(in_array('Create',$p,true)||in_array('Edit',$p,true)||in_array('Approve',$p,true))return true;foreach($p as $a)if(is_array($a)&&(in_array('Create',$a,true)||in_array('Edit',$a,true)||in_array('Approve',$a,true)))return true;return false;}
function pfo_def():array{return ['revision'=>0,'inventoryCostRates'=>[],'productionCostRuns'=>[],'salaryMasters'=>[],'rentMasters'=>[],'salaryPeriods'=>[],'rentPeriods'=>[]];}
function pfo_read():array{tt_ensure_data_dir();if(!is_file(TT_PFO_FILE))return pfo_def();$h=fopen(TT_PFO_FILE,'r');if($h===false||!flock($h,LOCK_SH))throw new RuntimeException('Accounts storage unavailable.');try{$raw=stream_get_contents($h);}finally{flock($h,LOCK_UN);fclose($h);}$v=$raw?json_decode($raw,true):null;return is_array($v)?array_replace_recursive(pfo_def(),$v):pfo_def();}
function pfo_ops():array{if(!is_file(TT_PFO_OPS))return ['values'=>[]];$h=fopen(TT_PFO_OPS,'r');if($h===false||!flock($h,LOCK_SH))return ['values'=>[]];try{$raw=stream_get_contents($h);}finally{flock($h,LOCK_UN);fclose($h);}$v=$raw?json_decode($raw,true):null;return is_array($v)?$v:['values'=>[]];}
function pfo_op(array $o,string $k):array{$raw=$o['values'][$k]??'';if(!is_string($raw)||$raw==='')return [];$v=json_decode($raw,true);return is_array($v)?$v:[];}
function pfo_entity(string $v):string{$v=strtoupper(trim($v));if(!in_array($v,['TTI','BRM'],true))pfo_out(['ok'=>false,'error'=>'Production fixed costs are available for TTI / BRM.'],422);return $v;}
function pfo_active(array $m,string $month):bool{if(($m['status']??'Active')!=='Active'||empty($m['productionCostEligible']))return false;$from=(string)($m['effectiveFrom']??'');$to=(string)($m['effectiveTo']??'');$start=$month.'-01';$end=(new DateTimeImmutable($start))->modify('last day of this month')->format('Y-m-d');return ($from===''||$from<=$end)&&($to===''||$to>=$start);}
function pfo_ready_kg_by_month(array $ops):array{$out=[];foreach(pfo_op($ops,'tt30prod') as $p){if(!is_array($p))continue;$date=(string)($p['date']??'');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))continue;$kg=0;foreach((array)($p['rows']??[]) as $r){if(!is_array($r)||(!empty($r['systemFixed'])&&!empty($r['noStockPost'])))continue;$name=strtoupper(trim((string)($r['product']??'')));if(!str_starts_with($name,'READY RICE'))continue;$x=(float)($r['systemKg']??0);if($x<=0)$x=(float)($r['bags']??0)*(float)($r['bagWeight']??0);$kg+=$x;}if($kg>0){$m=substr($date,0,7);$out[$m]=round(($out[$m]??0)+$kg,3);}}return $out;}
function pfo_month(array $s,string $entity,string $month,float $readyKg):array{$salary=0;$rent=0;$missing=[];foreach((array)$s['salaryMasters'] as $id=>$m){if(!is_array($m)||($m['entity']??'')!==$entity||!pfo_active($m,$month))continue;$pid=$entity.'|'.$month.'|'.$id;$p=$s['salaryPeriods'][$pid]??null;if(!is_array($p)){$missing[]='Salary: '.(string)($m['name']??$id);continue;}$salary+=round((float)($p['netSalary']??$m['monthlyAmount']??0)+(float)($p['otherAllowance']??$m['otherAllowance']??0),2);}foreach((array)$s['rentMasters'] as $id=>$m){if(!is_array($m)||($m['entity']??'')!==$entity||!pfo_active($m,$month))continue;$pid=$entity.'|'.$month.'|'.$id;$p=$s['rentPeriods'][$pid]??null;if(!is_array($p)){$missing[]='Rent: '.(string)($m['mill']??$id);continue;}$rent+=round((float)($p['gross']??$m['monthlyAmount']??0),2);}$total=round($salary+$rent,2);$perKg=$readyKg>0?round($total/$readyKg,6):0;return ['month'=>$month,'millSalary'=>round($salary,2),'millRent'=>round($rent,2),'totalFixedCost'=>$total,'readyRiceKg'=>$readyKg,'fixedCostPerReadyKg'=>$perKg,'missing'=>$missing,'ready'=>!$missing&&($total<=0||$readyKg>0),'status'=>$missing?'Waiting — prepare salary / rent month':($total>0&&$readyKg<=0?'Waiting — no Ready Rice production':'Ready')];}
function pfo_payload(array $s,string $entity):array{$kg=pfo_ready_kg_by_month(pfo_ops());$months=[];$keys=array_unique(array_merge(array_keys($kg),array_map(static fn($p)=>is_array($p)&&($p['entity']??'')===$entity?(string)($p['month']??''):'',(array)$s['salaryPeriods']),array_map(static fn($p)=>is_array($p)&&($p['entity']??'')===$entity?(string)($p['month']??''):'',(array)$s['rentPeriods'])));$keys=array_values(array_filter($keys));sort($keys);foreach($keys as $m)$months[$m]=pfo_month($s,$entity,$m,(float)($kg[$m]??0));return ['ok'=>true,'entity'=>$entity,'months'=>$months,'serverNow'=>gmdate('c')];}
function pfo_next(array $items,string $p):string{$n=count($items)+1;do{$id=$p.'-'.gmdate('Y').'-'.str_pad((string)$n,6,'0',STR_PAD_LEFT);$n++;}while(isset($items[$id]));return $id;}
try{$u=tt_require_login();if(!tt_user_can_open_module($u,'Accounts'))pfo_out(['ok'=>false,'error'=>'Accounts permission required.'],403);$entity=pfo_entity((string)($_GET['entity']??'TTI'));if($_SERVER['REQUEST_METHOD']==='GET')pfo_out(pfo_payload(pfo_read(),$entity));if($_SERVER['REQUEST_METHOD']!=='POST')pfo_out(['ok'=>false,'error'=>'Method not allowed.'],405);if(!pfo_can_write($u))pfo_out(['ok'=>false,'error'=>'Accounts approval permission required.'],403);$b=json_decode(file_get_contents('php://input')?:'{}',true);if(!is_array($b)||!tt_verify_csrf((string)($b['csrf']??'')))pfo_out(['ok'=>false,'error'=>'Your session expired. Refresh and try again.'],419);if(($b['action']??'')!=='apply_to_run')pfo_out(['ok'=>false,'error'=>'Unknown fixed-cost action.'],422);$groupId=trim((string)($b['groupId']??''));if($groupId==='')pfo_out(['ok'=>false,'error'=>'Production cost run is required.'],422);tt_ensure_data_dir();$h=fopen(TT_PFO_FILE,'c+');if($h===false||!flock($h,LOCK_EX))throw new RuntimeException('Accounts storage unavailable.');try{rewind($h);$raw=stream_get_contents($h);$s=$raw?json_decode($raw,true):null;if(!is_array($s))$s=pfo_def();$s=array_replace_recursive(pfo_def(),$s);$run=$s['productionCostRuns'][$groupId]??null;if(!is_array($run)||($run['entity']??'')!==$entity)pfo_out(['ok'=>false,'error'=>'Approve the base production cost first.'],422);$month=substr((string)$run['date'],0,7);$kg=pfo_ready_kg_by_month(pfo_ops());$fixed=pfo_month($s,$entity,$month,(float)($kg[$month]??0));if(empty($fixed['ready']))pfo_out(['ok'=>false,'error'=>(string)$fixed['status'],'missing'=>$fixed['missing']],422);$currentRateId=(string)($run['rateId']??'');$current=$s['inventoryCostRates'][$currentRateId]??null;if(!is_array($current))pfo_out(['ok'=>false,'error'=>'Approved production stock rate was not found.'],422);$base=(float)($run['baseCostPerKg']??$current['costPerKg']??0);if(isset($run['fixedOverheadRateId'])&&is_array($s['inventoryCostRates'][$run['fixedOverheadRateId']]??null)){$newId=(string)$run['fixedOverheadRateId'];}else{$newId=pfo_next((array)$s['inventoryCostRates'],'ICR');if($currentRateId!==$newId)$s['inventoryCostRates'][$currentRateId]['status']='Superseded';}$final=round($base+(float)$fixed['fixedCostPerReadyKg'],6);$s['inventoryCostRates'][$newId]=array_merge($current,['id'=>$newId,'costPerKg'=>$final,'status'=>'Active','source'=>'AUTO_PRODUCTION_COST_WITH_FIXED_OVERHEAD','notes'=>'Automatic production cost including prepared Mill Staff salary and Mill Rent for the month.','fixedOverhead'=>$fixed,'updatedAt'=>gmdate('c'),'updatedBy'=>(string)($u['full_name']??'Accounts')]);$s['productionCostRuns'][$groupId]['baseCostPerKg']=$base;$s['productionCostRuns'][$groupId]['fixedOverheadPerKg']=$fixed['fixedCostPerReadyKg'];$s['productionCostRuns'][$groupId]['fixedOverhead']=$fixed;$s['productionCostRuns'][$groupId]['fixedOverheadRateId']=$newId;$s['productionCostRuns'][$groupId]['rateId']=$newId;$s['productionCostRuns'][$groupId]['costPerKg']=$final;$s['productionCostRuns'][$groupId]['fixedOverheadAppliedAt']=gmdate('c');$s['revision']=(int)($s['revision']??0)+1;rewind($h);ftruncate($h,0);fwrite($h,json_encode($s,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));fflush($h);}finally{flock($h,LOCK_UN);fclose($h);}pfo_out(['ok'=>true,'groupId'=>$groupId,'rateId'=>$newId,'baseCostPerKg'=>$base,'fixedCostPerKg'=>$fixed['fixedCostPerReadyKg'],'finalCostPerKg'=>$final,'fixed'=>$fixed,'revision'=>$s['revision']]);}catch(Throwable $e){pfo_out(['ok'=>false,'error'=>'Production fixed-cost update could not be completed.'],500);}

